_MODE = make_sentinel('_MODE')


def _glom_fill(target, spec, scope):
    recurse = lambda val: scope[glom](target, val, scope)
    if isinstance(spec, dict):
        return type(spec)((recurse(key), recurse(val))
                          for key, val in spec.items())
    if isinstance(spec, (list, tuple, set, frozenset)):
        return type(spec)(recurse(val) for val in spec)
    if callable(spec):
        return spec(target)
    return spec


class Auto(object):
    """Evaluate *spec* with glom's normal transformation semantics.

    Useful for switching back to normal evaluation within :class:`Fill`.
    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        scope[_MODE] = _glom_auto
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        return 'Auto(%r)' % (self.spec,)


class Fill(object):
    """Build a literal structure, evaluating embedded specs and callables.

    Unlike normal glom evaluation, strings are literals, tuples are not
    pipelines, and lists describe their contents rather than iteration.
    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        scope[_MODE] = _glom_fill
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        return 'Fill(%r)' % (self.spec,)


class Let(object):
    """Bind named subspec results in scope, returning the original target.

    Bindings can be accessed by later specs in the pipeline using ``S``.
